 function parseOutline(text,limit=100){const rows=[],stack=[];for(const raw of String(text??'').replace(/\r/g,'').split('\n')){if(!raw.trim())continue;const indent=raw.match(/^[ \t]*/)[0].replace(/\t/g,'    ').length;let title=raw.trim();for(let i=0;i<2;i++)title=title.replace(/^(?:[-*•+]|\d{1,3}[.)]|\[[ xX]?\])(?:\s+|$)/,'');title=title.replace(/\s+/g,' ').trim().slice(0,200);if(!title)continue;while(stack.length&&stack[stack.length-1].indent>=indent)stack.pop();if(stack.length>=29)stack.pop();rows.push({title,parent:stack.length?stack[stack.length-1].index:null,depth:stack.length});stack.push({indent,index:rows.length-1});if(rows.length>limit)throw Error('Paste up to '+limit+' tasks at a time.');}return rows;}
