   if(d.can_complete&&['open','rejected'].includes(a.state))button(body,'Complete task',async()=>{await assignmentSend(base+'/assignments/'+id+'/complete',{revision:a.revision,task_revision:t.revision});await assignment(id);toast('Marked complete');});
   if(['owner','admin'].includes(g.role)&&writable)button(body,'Edit task',async()=>{const data=await api(base);await close(false);editor(data,t);});
   body.append(node('h4','Reference files'));for(const f of d.references)button(body,f.name,()=>download(f.id));
   if(['owner','admin'].includes(g.role)&&writable){const file=input(body,'Add reference (changes task revision)','','file');file.accept='.png,.jpg,.jpeg,.pdf,.txt';button(body,'Upload reference',async()=>{if(!file.files[0])throw Error('Select a reference file.');const fid=await upload(file.files[0],t,null,'reference');await assignmentSend(base+'/files/'+fid+'/attach',{task_revision:t.revision});await assignment(id);toast('Reference added');});}
   if(writable&&d.can_submit&&['open','rejected'].includes(a.state)){
    const reviewPath=t.audit_mode==='either'?select(body,'Choose review',[['ai','AI'],['human','Human']]):null;
    const text=input(body,'Proof text','','textarea',8000),files=input(body,'Proof files (up to three, 5 MiB each)','','file');files.multiple=true;files.accept='.png,.jpg,.jpeg,.pdf,.txt';
    button(body,'Submit proof',async()=>{if(files.files.length>3)throw Error('Choose up to three files.');const uploaded=[];for(const f of files.files)uploaded.push(await upload(f,t,a,'proof'));await assignmentSend(base+'/assignments/'+id+'/submit',{revision:a.revision,task_revision:t.revision,text:text.value,files:uploaded,...(reviewPath?{review_path:reviewPath.value}:{})});await assignment(id);toast('Proof submitted. It’s waiting for review.');});
   }
   body.append(node('h4','Submission history'));for(const s of d.submissions){const h=node('article');body.append(h);h.append(node('p',(window.TaskitatorI18n?.dateTime(s.created_at) ?? new Date(s.created_at).toLocaleString())+' · '+(members.find(m=>m.account_id===s.actor_id)?.username||'Member')+' · '+(s.decision?named('decision',s.decision):'Awaiting review')),node('p',s.text),node('p',s.reason||''));for(const fid of s.files||[])button(h,'Download proof',()=>download(fid));}
   if(a.state==='pending'&&d.submissions.some(s=>s.id===a.submission_id&&Date.now()-s.created_at>=86400000))body.append(node('p','Review is overdue. This assignment stays released from phone blocking while the review is pending.'));
   for(const s of d.submissions)if(s.actor_id===window.Clerk?.user?.id)for(const fid of s.files||[]){button(body,'Allow this proof attachment in Universe exports',async()=>{if(await ask('Allow this attachment to be downloaded in Universe backups by an owner or admin? Withdrawing permission cannot recall files already downloaded.'))await assignmentSend('/universe/groups/'+g.id+'/transfer/'+fid,{allowed:true});});button(body,'Withdraw export permission for this attachment',()=>assignmentSend('/universe/groups/'+g.id+'/transfer/'+fid,{allowed:false}));}
